export const WINDOWS_SETUP_TEMPLATE = "@echo off\nrem Bikas WhatsApp: one-click installer for Windows 10/11 (generated by the CRM; contains a secret key: do not send it to anyone).\nrem This batch part is plain ASCII: it only starts PowerShell, which runs the script stored below the #PAYLOAD line.\nrem The PowerShell script is UTF-8 (Russian texts). cmd never reads past \"exit /b\".\nsetlocal\ntitle Bikas WhatsApp\nset \"BK_SELF=%~f0\"\npowershell -NoProfile -ExecutionPolicy Bypass -Command \"& { $t = [IO.File]::ReadAllText($env:BK_SELF, [Text.Encoding]::UTF8); $p = [regex]::Split($t, '(?m)^#PAYLOAD\\s*$')[1]; & ([scriptblock]::Create($p)) }\"\nset \"BK_RC=%ERRORLEVEL%\"\necho.\npause\nexit /b %BK_RC%\n#PAYLOAD\n$ErrorActionPreference = 'Stop'\n$ProgressPreference = 'SilentlyContinue'\ntry { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch { }\ntry { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }\n\n# Filled in by the CRM when the file is downloaded.\n$CrmUrl = '__CRM_URL__'\n$Token = '__CONNECTOR_TOKEN__'\n\n$NodeVersion = '20.20.2'\n$Repo = 'sildar010386-cloud/ai-commerce-os'\n$Branch = 'claude/practical-mendel-vjtsd5'\n$TaskName = 'BikasWhatsApp'\n$Root = Join-Path $env:LOCALAPPDATA 'BikasWhatsApp'\n$NodeDir = Join-Path $Root 'node'\n$NodeExe = Join-Path $NodeDir 'node.exe'\n$Launcher = Join-Path $Root 'launcher.vbs'\n$StartupVbs = Join-Path ([Environment]::GetFolderPath('Startup')) 'BikasWhatsApp.vbs'\n$Utf8Bom = New-Object System.Text.UTF8Encoding($true)\n$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)\n\nfunction Say([string]$text, [string]$color = 'Gray') { Write-Host $text -ForegroundColor $color }\nfunction Step([string]$text) { Write-Host ''; Write-Host $text -ForegroundColor Cyan }\n\nfunction Stop-Bikas {\n  try { Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue } catch { }\n  for ($i = 0; $i -lt 3; $i++) {\n    $procs = @(Get-CimInstance Win32_Process | Where-Object { ($_.Name -eq 'wscript.exe' -or $_.Name -eq 'node.exe') -and $_.CommandLine -and $_.CommandLine.IndexOf($Root, [StringComparison]::OrdinalIgnoreCase) -ge 0 })\n    foreach ($p in $procs) { try { Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }\n    Start-Sleep -Milliseconds 700\n  }\n}\n\nfunction Test-Running {\n  $procs = @(Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -and $_.CommandLine.IndexOf('supervisor.js', [StringComparison]::OrdinalIgnoreCase) -ge 0 -and $_.CommandLine.IndexOf($Root, [StringComparison]::OrdinalIgnoreCase) -ge 0 })\n  return ($procs.Count -gt 0)\n}\n\nfunction Test-Crm {\n  try {\n    $r = Invoke-WebRequest -UseBasicParsing -Uri ($CrmUrl.TrimEnd('/') + '/api/connector/outbox?ready=0') -Headers @{ Authorization = \"Bearer $Token\" } -TimeoutSec 25\n    return ($r.StatusCode -eq 200)\n  } catch {\n    $code = 0\n    try { $code = [int]$_.Exception.Response.StatusCode } catch { }\n    if ($code -eq 401) { throw 'Ключ подключения устарел или неверный. Откройте CRM, снова нажмите «Скачать установщик для Windows» и запустите новый файл.' }\n    throw ('Не удалось связаться с CRM (' + $CrmUrl + '). Проверьте интернет и запустите файл ещё раз.')\n  }\n}\n\nfunction Install-Node {\n  if (Test-Path -LiteralPath $NodeExe) {\n    $v = ''\n    try { $v = (& $NodeExe --version 2>$null) } catch { }\n    if ($v -eq ('v' + $NodeVersion)) { Say 'Node.js уже установлен.'; return }\n  }\n  $tmp = Join-Path $Root 'tmp'\n  if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force }\n  New-Item -ItemType Directory -Path $tmp -Force | Out-Null\n  $zipName = 'node-v' + $NodeVersion + '-win-x64.zip'\n  $base = 'https://nodejs.org/dist/v' + $NodeVersion + '/'\n  $sums = (Invoke-WebRequest -UseBasicParsing -Uri ($base + 'SHASUMS256.txt')).Content\n  if ($sums -is [byte[]]) { $sums = [Text.Encoding]::ASCII.GetString($sums) }\n  $line = @($sums -split \"`n\" | Where-Object { $_ -match ([regex]::Escape($zipName) + '\\s*$') })[0]\n  $expected = ''\n  if ($line) { $expected = ($line.Trim() -split '\\s+')[0].ToLower() }\n  if ($expected.Length -ne 64) { throw 'Не получилось проверить Node.js (нет контрольной суммы).' }\n  $zip = Join-Path $tmp $zipName\n  Say 'Скачиваю Node.js (около 30 МБ)...'\n  Invoke-WebRequest -UseBasicParsing -Uri ($base + $zipName) -OutFile $zip\n  $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $zip).Hash.ToLower()\n  if ($actual -ne $expected) { throw 'Контрольная сумма Node.js не совпала: файл повреждён при скачивании. Запустите установщик ещё раз.' }\n  Say 'Распаковываю...'\n  Add-Type -AssemblyName System.IO.Compression.FileSystem\n  $out = Join-Path $tmp 'x'\n  [IO.Compression.ZipFile]::ExtractToDirectory($zip, $out)\n  if (Test-Path -LiteralPath $NodeDir) { Remove-Item -LiteralPath $NodeDir -Recurse -Force }\n  Move-Item -LiteralPath (Join-Path $out ('node-v' + $NodeVersion + '-win-x64')) -Destination $NodeDir\n  Remove-Item -LiteralPath $tmp -Recurse -Force\n  $v = (& $NodeExe --version 2>$null)\n  if ($v -ne ('v' + $NodeVersion)) { throw 'Node.js не запускается на этом компьютере.' }\n}\n\nfunction Install-Code {\n  $boot = Join-Path $Root 'bootstrap'\n  New-Item -ItemType Directory -Path $boot -Force | Out-Null\n  $bootFile = Join-Path $boot 'update.mjs'\n  $url = 'https://raw.githubusercontent.com/' + $Repo + '/' + $Branch + '/connector/src/update.js'\n  Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $bootFile\n  $env:PATH = $NodeDir + ';' + $env:PATH\n  & $NodeExe $bootFile install $Root --force\n  if ($LASTEXITCODE -ne 0) { throw 'Не получилось скачать и установить программу подключения. Проверьте интернет и запустите файл ещё раз.' }\n  if (-not (Test-Path -LiteralPath (Join-Path $Root 'app\\src\\supervisor.js'))) { throw 'Программа подключения установлена не полностью.' }\n}\n\nfunction Write-Config {\n  $cfg = Join-Path $Root 'config.env'\n  $text = \"CRM_URL=\" + $CrmUrl + \"`r`nCONNECTOR_TOKEN=\" + $Token + \"`r`nBIKAS_AUTOUPDATE=1`r`n\"\n  [IO.File]::WriteAllText($cfg, $text, $Utf8NoBom)\n  # readable only by this Windows user\n  $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value\n  & icacls.exe $cfg /inheritance:r /grant:r ('*' + $sid + ':(F)') | Out-Null\n  if ($LASTEXITCODE -ne 0) { Say 'Не удалось ограничить доступ к файлу config.env (это не мешает работе).' 'Yellow' }\n}\n\n$ToolsPs1 = @'\nparam([string]$Action)\n$ErrorActionPreference = 'Continue'\ntry { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch { }\n$Root = Join-Path $env:LOCALAPPDATA 'BikasWhatsApp'\n$TaskName = 'BikasWhatsApp'\n$Launcher = Join-Path $Root 'launcher.vbs'\n$StartupVbs = Join-Path ([Environment]::GetFolderPath('Startup')) 'BikasWhatsApp.vbs'\n\nfunction Stop-Bikas {\n  try { Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue } catch { }\n  for ($i = 0; $i -lt 3; $i++) {\n    $procs = @(Get-CimInstance Win32_Process | Where-Object { ($_.Name -eq 'wscript.exe' -or $_.Name -eq 'node.exe') -and $_.CommandLine -and $_.CommandLine.IndexOf($Root, [StringComparison]::OrdinalIgnoreCase) -ge 0 })\n    foreach ($p in $procs) { try { Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }\n    Start-Sleep -Milliseconds 700\n  }\n}\nfunction Test-Running {\n  $procs = @(Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'node.exe' -and $_.CommandLine -and $_.CommandLine.IndexOf('supervisor.js', [StringComparison]::OrdinalIgnoreCase) -ge 0 -and $_.CommandLine.IndexOf($Root, [StringComparison]::OrdinalIgnoreCase) -ge 0 })\n  return ($procs.Count -gt 0)\n}\nfunction Start-Bikas {\n  if (Test-Running) { return }\n  $started = $false\n  try { if (Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop) { Start-ScheduledTask -TaskName $TaskName -ErrorAction Stop; $started = $true } } catch { }\n  if ($started) { Start-Sleep -Seconds 4 }\n  if (-not (Test-Running)) {\n    Start-Process -FilePath 'wscript.exe' -ArgumentList @('//B', '//Nologo', ('\"' + $Launcher + '\"')) -WindowStyle Hidden\n    Start-Sleep -Seconds 4\n  }\n}\n\nif ($Action -eq 'stop') {\n  Stop-Bikas\n  if (Test-Running) { Write-Host 'Не получилось остановить. Перезагрузите компьютер.' -ForegroundColor Red }\n  else { Write-Host 'Остановлено. Сообщения из WhatsApp не поступают в CRM, пока подключение выключено.' -ForegroundColor Green; Write-Host 'Чтобы включить снова, откройте «Запустить.cmd» (или перезайдите в Windows).' }\n}\nelseif ($Action -eq 'start') {\n  if (-not (Test-Path -LiteralPath (Join-Path $Root 'app\\src\\supervisor.js'))) { Write-Host 'Подключение не установлено. Скачайте установщик в CRM и запустите его.' -ForegroundColor Red }\n  else {\n    Start-Bikas\n    if (Test-Running) { Write-Host 'Запущено. Окно можно закрыть: подключение работает в фоне.' -ForegroundColor Green }\n    else { Write-Host 'Не удалось запустить. Посмотрите файл connector.log в папке программы.' -ForegroundColor Red }\n  }\n}\nelseif ($Action -eq 'uninstall') {\n  Write-Host 'Будет удалено подключение WhatsApp к CRM с этого компьютера: программа, автозапуск и сохранённый вход в WhatsApp.' -ForegroundColor Yellow\n  Write-Host 'Сообщения и чаты в CRM остаются. Подключить заново можно, скачав установщик в CRM.'\n  $a = Read-Host 'Чтобы удалить, введите слово ДА и нажмите Enter (любой другой ответ отменит удаление)'\n  if (@('ДА', 'DA', 'YES', 'Y') -notcontains $a.Trim().ToUpper()) { Write-Host 'Отменено. Ничего не удалено.' }\n  else {\n    Stop-Bikas\n    try { Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch { }\n    try { Remove-Item -LiteralPath $StartupVbs -Force -ErrorAction SilentlyContinue } catch { }\n    Set-Location -LiteralPath $env:TEMP\n    for ($i = 0; $i -lt 4; $i++) {\n      try { if (Test-Path -LiteralPath $Root) { Remove-Item -LiteralPath $Root -Recurse -Force -ErrorAction Stop } } catch { Start-Sleep -Seconds 2 }\n    }\n    if (Test-Path -LiteralPath $Root) { Write-Host 'Часть файлов не удалилась (занята другой программой). Перезагрузите компьютер и удалите папку вручную:' -ForegroundColor Red; Write-Host $Root }\n    else { Write-Host 'Удалено.' -ForegroundColor Green }\n    Write-Host 'Осталось один раз на телефоне: WhatsApp → Связанные устройства → выберите это устройство → Выйти.'\n  }\n}\n'@\n\nfunction Write-Support {\n  $vbs = 'Set sh = CreateObject(\"WScript.Shell\")' + \"`r`n\" +\n    'root = \"' + $Root + '\"' + \"`r`n\" +\n    'sh.CurrentDirectory = root' + \"`r`n\" +\n    'sh.Environment(\"Process\")(\"BIKAS_HOME\") = root' + \"`r`n\" +\n    'Do' + \"`r`n\" +\n    '  rc = sh.Run(\"\"\"\" & root & \"\\node\\node.exe\"\" \"\"\" & root & \"\\app\\src\\supervisor.js\"\"\", 0, True)' + \"`r`n\" +\n    '  If rc = 99 Then Exit Do' + \"`r`n\" +\n    '  WScript.Sleep 10000' + \"`r`n\" +\n    'Loop' + \"`r`n\"\n  [IO.File]::WriteAllText($Launcher, $vbs, [Text.Encoding]::Unicode)\n  [IO.File]::WriteAllText((Join-Path $Root 'tools.ps1'), ($ToolsPs1 -replace \"`r?`n\", \"`r`n\"), $Utf8Bom)\n  $names = @{ 'stop' = 'Остановить.cmd'; 'start' = 'Запустить.cmd'; 'uninstall' = 'Удалить.cmd' }\n  foreach ($k in $names.Keys) {\n    $cmd = '@echo off' + \"`r`n\" +\n      'copy /y \"%~dp0tools.ps1\" \"%TEMP%\\bikas-tools.ps1\" >nul' + \"`r`n\" +\n      'powershell -NoProfile -ExecutionPolicy Bypass -File \"%TEMP%\\bikas-tools.ps1\" ' + $k + \"`r`n\" +\n      'pause' + \"`r`n\"\n    [IO.File]::WriteAllText((Join-Path $Root $names[$k]), $cmd, [Text.Encoding]::ASCII)\n  }\n}\n\nfunction Register-Autostart {\n  $user = [Security.Principal.WindowsIdentity]::GetCurrent().Name\n  try {\n    $action = New-ScheduledTaskAction -Execute 'wscript.exe' -Argument ('//B //Nologo \"' + $Launcher + '\"')\n    $trigger = New-ScheduledTaskTrigger -AtLogOn -User $user\n    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew\n    $principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited\n    Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force -ErrorAction Stop | Out-Null\n    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop) {\n      try { Remove-Item -LiteralPath $StartupVbs -Force -ErrorAction SilentlyContinue } catch { }\n      return 'task'\n    }\n  } catch { }\n  # No rights for a scheduled task: a small hidden script in the Startup folder does the same at logon.\n  try { Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch { }\n  $stub = 'CreateObject(\"WScript.Shell\").Run \"wscript.exe //B //Nologo \"\"' + $Launcher + '\"\"\", 0, False' + \"`r`n\"\n  [IO.File]::WriteAllText($StartupVbs, $stub, [Text.Encoding]::Unicode)\n  return 'startup'\n}\n\ntry {\n  Write-Host ''\n  Write-Host 'Установка подключения WhatsApp для CRM Bikas' -ForegroundColor White\n  Write-Host 'Папка установки: ' $Root\n  if (-not [Environment]::Is64BitOperatingSystem) { throw 'Нужна 64-разрядная Windows 10 или 11.' }\n  if ($PSVersionTable.PSVersion.Major -lt 5) { throw 'Нужна Windows 10 или 11 (устаревший PowerShell).' }\n  if (-not $env:LOCALAPPDATA) { throw 'Не найдена папка пользователя Windows.' }\n\n  Step '[1/6] Проверяю связь с CRM...'\n  Test-Crm | Out-Null\n  Say 'Связь есть, ключ подключения принят.' 'Green'\n\n  Step '[2/6] Останавливаю старую копию (если она была)...'\n  New-Item -ItemType Directory -Path $Root -Force | Out-Null\n  Stop-Bikas\n\n  Step '[3/6] Устанавливаю Node.js (нужен только этой программе)...'\n  Install-Node\n\n  Step '[4/6] Скачиваю и устанавливаю программу подключения (1-3 минуты)...'\n  Install-Code\n\n  Step '[5/6] Сохраняю настройки и создаю автозапуск...'\n  New-Item -ItemType Directory -Path (Join-Path $Root 'data') -Force | Out-Null   # the WhatsApp session lives here and is never deleted\n  Write-Config\n  Write-Support\n  $mode = Register-Autostart\n  if ($mode -eq 'task') { Say 'Автозапуск при входе в Windows настроен.' 'Green' }\n  else { Say 'Автозапуск настроен через папку «Автозагрузка».' 'Green' }\n\n  Step '[6/6] Запускаю подключение...'\n  $tries = 0\n  $ok = $false\n  while ($tries -lt 3 -and -not $ok) {\n    $tries++\n    if ($mode -eq 'task' -and $tries -eq 1) { try { Start-ScheduledTask -TaskName $TaskName -ErrorAction Stop } catch { } }\n    else { Start-Process -FilePath 'wscript.exe' -ArgumentList @('//B', '//Nologo', ('\"' + $Launcher + '\"')) -WindowStyle Hidden }\n    Start-Sleep -Seconds 5\n    $ok = Test-Running\n  }\n  if (-not $ok) { throw 'Подключение не запустилось. Посмотрите файл connector.log в папке установки.' }\n\n  Write-Host ''\n  Write-Host 'Готово. Откройте CRM → Настройки → Подключение WhatsApp и отсканируйте QR-код' -ForegroundColor Green\n  Write-Host ''\n  Write-Host 'Важно: пока ноутбук включён и есть интернет, сообщения приходят в CRM. Когда он выключен, WhatsApp хранит их и отдаёт при следующем включении.'\n  Write-Host ('В папке ' + $Root + ' есть файлы «Остановить.cmd», «Запустить.cmd» и «Удалить.cmd».')\n  exit 0\n} catch {\n  Write-Host ''\n  Write-Host ('Не получилось: ' + $_.Exception.Message) -ForegroundColor Red\n  Write-Host 'Запустите файл ещё раз. Если снова ошибка, сфотографируйте это окно и отправьте разработчику.'\n  exit 1\n}\n";
